window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cdecb52d265bf3a1"]={"versions": [{"id": "FIG-cdecb52d265bf3a1", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-ECU-Konfigurationsparameter (BSW-Modul Diagnostic Event Manager, Dem). Das Diagramm definiert das Metamodell für zeitbasierte Entprellklassen (<code>DemDebounceTimeBaseClass</code>) innerhalb des übergeordneten Konfigurationscontainers <code>DemConfigSet</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Konfigurationselemente und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>DemConfigSet</code>: Container-Definition (<code>EcucParamConfContainerDef</code>), aggregiert über die Komposition <code>+subContainer</code> das Element <code>DemDebounceTimeBaseClass</code>.\n</li><li><code>DemDebounceTimeBaseClass</code>: Container (<code>EcucParamConfContainerDef</code>) mit Multiplizität 0..65535 (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 65535</code>), aggregiert via <code>+parameter</code> folgende Parameter:\n<ul class=\"fig-list\"><li><code>DemDebounceTimeFailedThreshold</code>: Fließkommaparameter (<code>EcucFloatParamDef</code>) mit <code>min = 0.001</code> und <code>max = 3600.0</code> (Zeitdauer bis zum Failed-Status in Sekunden).\n</li><li><code>DemDebounceTimePassedThreshold</code>: Fließkommaparameter (<code>EcucFloatParamDef</code>) mit <code>min = 0.001</code> und <code>max = 3600.0</code> (Zeitdauer bis zum Passed-Status in Sekunden).\n</li><li><code>DemDebounceBehavior</code>: Enumerationsparameter (<code>EcucEnumerationParamDef</code>, Multiplizität 1..1), aggregiert über <code>+literal</code> die Literale <code>DEM_DEBOUNCE_FREEZE</code> und <code>DEM_DEBOUNCE_RESET</code>.\n</li><li><code>DemTimeBasedFdcThresholdStorageValue</code>: Optionaler Fließkommaparameter (<code>EcucFloatParamDef</code>, <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>) mit <code>min = 0.001</code> und <code>max = 3600</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenmodell ohne dynamische Ablauf- oder Sequenzdarstellung. Die Parameter definieren das zeitgesteuerte Entprellverhalten bei Event-Meldungen: <code>DemDebounceTimeFailedThreshold</code> steuert den Zeitverlauf bis zur Fehlervalidierung, <code>DemDebounceTimePassedThreshold</code> bis zur Gutprüfung. <code>DemDebounceBehavior</code> bestimmt, ob der interne Timer bei Deaktivierung bzw. Statuswechsel eingefroren (<code>FREEZE</code>) oder zurückgesetzt (<code>RESET</code>) wird. <code>DemTimeBasedFdcThresholdStorageValue</code> definiert die Schwelle für die Erfassung von Fault-Detection-Counter-Werten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsvorgabe für AUTOSAR Dem-Generatoren und BSW-Entwickler. Die Multiplizitäten regeln die Instanziierbarkeit der Entprellklassen (bis zu 65535 Klassen pro Config-Set) sowie die Pflichtbelegung von Schwellwerten und Entprellstrategie. Fließkommagrenzen stellen die Validierungsregeln für Konfigurationswerkzeuge (Tresos, DaVinci etc.) dar.</p>"}, {"id": "FIG-aae8cc9805c1559d", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-ECU-Konfigurationsparameter (BSW-Modul Diagnostic Event Manager, Dem). Das Diagramm definiert das Metamodell für zeitbasierte Entprellklassen (<code>DemDebounceTimeBaseClass</code>) innerhalb des übergeordneten Konfigurationscontainers <code>DemConfigSet</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Konfigurationselemente und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>DemConfigSet</code>: Container-Definition (<code>EcucParamConfContainerDef</code>), aggregiert über die Komposition <code>+subContainer</code> das Element <code>DemDebounceTimeBaseClass</code>.\n</li><li><code>DemDebounceTimeBaseClass</code>: Container (<code>EcucParamConfContainerDef</code>) mit Multiplizität 0..65535 (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 65535</code>), aggregiert via <code>+parameter</code> folgende Parameter:\n<ul class=\"fig-list\"><li><code>DemDebounceTimeFailedThreshold</code>: Fließkommaparameter (<code>EcucFloatParamDef</code>) mit <code>min = 0.001</code> und <code>max = 3600.0</code> (Zeitdauer bis zum Failed-Status in Sekunden).\n</li><li><code>DemDebounceTimePassedThreshold</code>: Fließkommaparameter (<code>EcucFloatParamDef</code>) mit <code>min = 0.001</code> und <code>max = 3600.0</code> (Zeitdauer bis zum Passed-Status in Sekunden).\n</li><li><code>DemDebounceBehavior</code>: Enumerationsparameter (<code>EcucEnumerationParamDef</code>, Multiplizität 1..1), aggregiert über <code>+literal</code> die Literale <code>DEM_DEBOUNCE_FREEZE</code> und <code>DEM_DEBOUNCE_RESET</code>.\n</li><li><code>DemTimeBasedFdcThresholdStorageValue</code>: Optionaler Fließkommaparameter (<code>EcucFloatParamDef</code>, <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>) mit <code>min = 0.001</code> und <code>max = 3600</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenmodell ohne dynamische Ablauf- oder Sequenzdarstellung. Die Parameter definieren das zeitgesteuerte Entprellverhalten bei Event-Meldungen: <code>DemDebounceTimeFailedThreshold</code> steuert den Zeitverlauf bis zur Fehlervalidierung, <code>DemDebounceTimePassedThreshold</code> bis zur Gutprüfung. <code>DemDebounceBehavior</code> bestimmt, ob der interne Timer bei Deaktivierung bzw. Statuswechsel eingefroren (<code>FREEZE</code>) oder zurückgesetzt (<code>RESET</code>) wird. <code>DemTimeBasedFdcThresholdStorageValue</code> definiert die Schwelle für die Erfassung von Fault-Detection-Counter-Werten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsvorgabe für AUTOSAR Dem-Generatoren und BSW-Entwickler. Die Multiplizitäten regeln die Instanziierbarkeit der Entprellklassen (bis zu 65535 Klassen pro Config-Set) sowie die Pflichtbelegung von Schwellwerten und Entprellstrategie. Fließkommagrenzen stellen die Validierungsregeln für Konfigurationswerkzeuge (Tresos, DaVinci etc.) dar.</p>"}], "trans": [{"from": "FIG-cdecb52d265bf3a1", "to": "FIG-aae8cc9805c1559d", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Leerzeichen vor den Doppelpunkten bei Klassennamen/Containernamen (<code>DemConfigSet:</code>, <code>DemDebounceTimeBaseClass:</code>, <code>DemDebounceTimeFailedThreshold:</code>, <code>DemDebounceTimePassedThreshold:</code>, <code>DemDebounceBehavior:</code>, <code>DEM_DEBOUNCE_FREEZE:</code>, <code>DEM_DEBOUNCE_RESET:</code>, <code>DemTimeBasedFdcThresholdStorageValue:</code>) entfernt.\n</li></ul>"}]};
